import functools
class C:
 @functools.singledispatchmethod
 def f(self,value):
  with open("value") as file:return int(file.read())+value
print(C().f(2))

import functools
class C:
 @functools.singledispatchmethod
 def f(self,value):return 0
 @f.register(int)
 def integer(self,value):
  with open("value") as file:return int(file.read())+value
print(C().f(2))

import functools
class C:
 def f(self,a,b):
  with open("value") as file:return int(file.read())+a+b
 g=functools.partialmethod(f,2)
print(C().g(3))

import functools
class C:
 @functools.cached_property
 def value(self):
  with open("value") as file:return int(file.read())
x=C()
print(x.value,x.value)

import functools
@functools.recursive_repr()
def render(value):
 with open("value") as file:return file.read()
print(render(2))

import functools
class Wrapped:
 @property
 def tag(self):
  with open("value") as file:return file.read()
def wrapper():pass
functools.update_wrapper(wrapper,Wrapped(),assigned=("tag",),updated=())
print(wrapper.tag)

import functools
class Flag:
 def __bool__(self):
  with open("value") as file:return int(file.read())==0
@functools.lru_cache(typed=Flag())
def f(x):return type(x).__name__
print(f(1.0),f(True))
